import { useEffect, useMemo, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import './room.css';
import { searchRooms } from './services/hotels';

export default function SearchResults() {
  const location = useLocation();
  const navigate = useNavigate();
  const incoming = location.state || {};

  const [destination, setDestination] = useState(incoming.destination || '');
  const [guests, setGuests] = useState(incoming.guests || 1);
  const checkIn = incoming.checkIn || '';
  const checkOut = incoming.checkOut || '';

  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    let mounted = true;
    setLoading(true);
    setError('');
    searchRooms({ checkIn, checkOut })
      .then((data) => {
        if (!mounted) return;
        setRooms(Array.isArray(data) ? data : []);
      })
      .catch((err) => {
        if (!mounted) return;
        setError(err.message || 'Unable to load rooms.');
      })
      .finally(() => {
        if (!mounted) return;
        setLoading(false);
      });
    return () => {
      mounted = false;
    };
  }, [checkIn, checkOut]);

  const results = useMemo(() => {
    const destValue = destination.trim().toLowerCase();
    return rooms.filter((room) => {
      const okCity = !destValue || String(room.city || '').toLowerCase().includes(destValue);
      const okGuests = !guests || room.capacity >= Number(guests);
      return okCity && okGuests;
    });
  }, [rooms, destination, guests]);

  const handleBook = (room) => {
    navigate('/reservation', {
      state: {
        room: {
          id: room.id,
          hotelId: room.hotelId,
          name: room.name,
          hotel: room.hotelName,
          city: room.city,
          price: room.price,
          rating: room.stars,
          img: room.photos?.[0],
          capacity: room.capacity,
          amount: room.amount,
        },
        checkIn,
        checkOut,
        guests,
      },
    });
  };

  const dateSummary = checkIn && checkOut ? `${checkIn} → ${checkOut}` : null;

  return (
    <div className="rooms-page">
      <div className="back-wrapper">
        <button type="button" className="back-btn" onClick={() => navigate('/')}>← Back to home</button>
      </div>

      <h1 className="section-title">
        {destination ? `Rooms in ${destination}` : 'Search Results'}
      </h1>
      <p style={{ textAlign: 'center', marginBottom: 20, color: '#5c677d' }}>
        {dateSummary && <>{dateSummary} · </>}
        {guests} {Number(guests) === 1 ? 'guest' : 'guests'} · {results.length} room{results.length === 1 ? '' : 's'} found
      </p>

      {loading && <p style={{ textAlign: 'center', marginBottom: 20 }}>Loading rooms...</p>}
      {error && <p style={{ textAlign: 'center', color: '#9b1c1c', marginBottom: 20 }}>{error}</p>}

      <div className="filters-wrapper">
        <div className="filters-row">
          <input
            placeholder="Where do you want to go?"
            value={destination}
            onChange={(e) => setDestination(e.target.value)}
          />
          <input
            type="number"
            min={1}
            placeholder="Guests"
            value={guests}
            onChange={(e) => setGuests(Number(e.target.value) || 1)}
          />
        </div>
      </div>

      <div className="rooms-grid">
        {results.map((room) => (
          <div key={room.id} className="room-card snow-card">
            {room.photos?.[0] && <img className="room-img" src={room.photos[0]} alt={room.name} />}
            <h3>{room.name}</h3>
            <p className="hotel-name">{room.hotelName} · {room.city || 'City not set'}</p>
            <p className="room-info">
              ${room.price}/night · Sleeps {room.capacity} · {'★'.repeat(room.stars)}
            </p>
            <button className="book-btn" onClick={() => handleBook(room)}>Book Now</button>
          </div>
        ))}
        {!loading && !error && results.length === 0 && (
          <div className="empty-state">
            <p>No rooms match your search.</p>
          </div>
        )}
      </div>
    </div>
  );
}
